# site 站点静态托管桶（IaC）
#
# 桶 [BUCKET]：命名对齐站点规范 {repo}-{type}（如 [BUCKET] / qtmedia-site）。
# 产物：纯静态站点（src/site，build.py 生成 stores/ 后整体上传）。
# 静态网站托管：index.html 默认首页（example.com 根路径）。
# 部署流水线：.github/project/src/file42.yml（site/* tag 触发 → build.py → ossutil cp → 刷新 CDN）。

resource "alicloud_oss_bucket" "site" {
  bucket = "[BUCKET]"

  # 静态网站托管（门户入口 index.html）
  website {
    index_document = "index.html"
    error_document = "404.html"
  }
}

# 2023 后新桶默认开启"阻止公共访问"，会使 public-read 失效（AccessDenied），
# 需显式关闭（qtcloud-studio 桶踩过此坑，见 manifests/project/src/file82.md）
resource "alicloud_oss_bucket_public_access_block" "site" {
  bucket              = alicloud_oss_bucket.site.bucket
  block_public_access = false
}

# 公共读：站点静态资源分发；如后续接入 CDN 回源鉴权可改回 private
resource "alicloud_oss_bucket_acl" "site" {
  bucket = alicloud_oss_bucket.site.bucket
  acl    = "public-read"
}

# 阿里云凭证通过环境变量注入（不在代码中写死）：
#   export ALICLOUD_ACCESS_KEY=...
#   export ALICLOUD_SECRET_KEY=...
provider "alicloud" {
  region = var.region
}

# 远程状态：OSS（本机与 CI 共用，CI 必须持久化状态）。初始化时通过 -backend-config 指定：
#   terraform init \
#   -backend-config="bucket=[BUCKET]" \
#     -backend-config="key=qtstore/terraform.tfstate" \
#     -backend-config="region=cn-hangzhou"
terraform {
  backend "oss" {}
}

variable "region" {
  description = "阿里云地域"
  type        = string
  default     = "cn-hangzhou"
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    alicloud = {
      source  = "aliyun/alicloud"
      version = "~> 1.240"
    }
  }
}

output "site_bucket" {
  description = "站点发布分发桶（部署产物见 .github/project/src/file42.yml）"
  value       = alicloud_oss_bucket.site.bucket
}
